if (run.status !== 0) {
  console.error("ERROR: vitest run --reporter=blob exited " + run.status);
  process.exit(2);
}
const blob = path.join(dir, ".vitest", "blob", "blob.json");
if (!fs.existsSync(blob)) {
  console.log(".vitest-reports exists: " + fs.existsSync(path.join(dir, ".vitest-reports")));
  console.error("FAIL: the blob reporter did not write .vitest/blob/blob.json by default");
  process.exit(1);
}
// --merge-reports without a path must read the same default folder.
const merge = vitest(["run", "--merge-reports"]);
console.log(merge.out);
if (merge.status !== 0 || !/1 passed/.test(merge.out)) {
  console.error("FAIL: --merge-reports without a path did not merge .vitest/blob (exit " + merge.status + ")");
  process.exit(1);
}
console.log("PASS: blob report written to and merged from .vitest/blob/");

